const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Lake Menindee, Australia
  const lakeGeometry = ee.Geometry.Point([142.395, -32.402]).buffer(15000);

  // Date windows
  const date1Start = '2017-01-20';
  const date1End = '2017-02-03';
  const date2Start = '2019-01-26';
  const date2End = '2019-02-09';

  // Landsat 8 collection with cloud/shadow masking
  function filterAndMask(startDate, endDate) {
    let col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeGeometry)
      .filterDate(startDate, endDate)
      .map(function(img) {
        // Cloud and shadow mask using QA_PIXEL
        const qaPixel = img.select('QA_PIXEL');
        const cloud = qaPixel.bitwiseAnd(1 << 3).eq(0); // Cloud bit
        const shadow = qaPixel.bitwiseAnd(1 << 4).eq(0); // Cloud shadow bit
        const mask = cloud.and(shadow);
        return img.updateMask(mask);
      });
    return col;
  }

  // Get collections
  const col1 = filterAndMask(date1Start, date1End);
  const col2 = filterAndMask(date2Start, date2End);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    print('Jan 2017 Images: ' + size1 + ', Feb 2019 Images: ' + size2);
    print('<answer>C1</answer>');
    return;
  }

  // Median composite for each period
  const img1 = col1.median();
  const img2 = col2.median();

  // Calculate NDWI
  function calcNDWI(img) {
    const green = img.select('SR_B3');
    const nir = img.select('SR_B5');
    return nir.subtract(green).divide(nir.add(green)).rename('NDWI');
  }

  const ndwi1 = calcNDWI(img1);
  const ndwi2 = calcNDWI(img2);

  // Water detection (NDWI > 0.3)
  const water1 = ndwi1.gt(0.3).rename('water');
  const water2 = ndwi2.gt(0.3).rename('water');

  // Count water pixels
  const count1 = water1.reduceRegion(
    ee.Reducer.count(),
    lakeGeometry,
    30,
    null,
    null,
    false,
    1e9
  ).getInfo();

  const count2 = water2.reduceRegion(
    ee.Reducer.count(),
    lakeGeometry,
    30,
    null,
    null,
    false,
    1e9
  ).getInfo();

  const pixels1 = count1.water || 0;
  const pixels2 = count2.water || 0;

  print('Jan 2017 Water Pixels: ' + pixels1);
  print('Feb 2019 Water Pixels: ' + pixels2);

  if (pixels1 === 0 || pixels2 === 0) {
    print('<answer>C2</answer>');
    return;
  }

  // Calculate area (30m resolution)
  const area1 = pixels1 * 900 / 1e6; // km²
  const area2 = pixels2 * 900 / 1e6; // km²

  print('Jan 2017 Area: ' + area1.toFixed(2) + ' km²');
  print('Feb 2019 Area: ' + area2.toFixed(2) + ' km²');
  print('Change: ' + (area2 - area1).toFixed(2) + ' km²');

  if (area1 > area2) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
